    const line = getNodeLine(ts, sf, node);

    if (ts.isBlock(node)) {
      inspectEarlyReturnInBlock(ts, sf, node, ctx, state);
    }

    if (ts.isTryStatement(node)) {
      inspectTryStatement(ts, sf, node, line, ctx, state);
    }

    // Empty custom assertion helper (`AITEST-G113`)
