        const ev = {
          line,
          scopeKind: ctx.scopeKind,
          testTitle: ctx.testTitle,
          snippet: node.name.text,
          message: `${fileLabel}: custom assertion helper "${node.name.text}" contains zero real expect() calls.`,
        };
