          calleeText,
          line,
          scopeKind: ctx.scopeKind,
          testTitle: ctx.testTitle,
          isStandaloneGuard: false,
          isCapabilityGuard: false,
          snippet: rawCall.slice(0, 160),
          message: `${fileLabel}: added expectation-inverting .fail() ("${firstLine}").`,
