            ts.isPropertyAssignment(p) &&
            ((ts.isIdentifier(p.name) && p.name.text === 'soft') ||
              (ts.isStringLiteral(p.name) && p.name.text === 'soft')) &&
            unwrapExpr(ts, p.initializer).kind === ts.SyntaxKind.TrueKeyword
