            kind: 'expect.configure',
            line,
            scopeKind: ctx.scopeKind,
            testTitle: ctx.testTitle,
            snippet: node.getText(sf),
            message: `${fileLabel}: expect.configure({ soft: true }) globally weakens assertions to soft mode.`,
